      sources: [{ name: "地方自治体の街路樹に関する維持管理計画および住民参加制度の状況", url: "https://www.jstage.jst.go.jp/article/jila/83/5/83_509/_article/-char/ja", usedFor: "住民参加が維持管理体制の上に置かれる背景" }, { name: "住民参加型の道路維持管理活動を行う団体への行政支援の効果に関する研究", url: "https://www.jstage.jst.go.jp/article/aijt/32/80/32_446/_article/-char/ja", usedFor: "道具・中間支援・行政コミュニケーションが運営に関わる観察材料" }],
