      sources: [{ name: "地方自治体の街路樹に関する維持管理計画および住民参加制度の状況", url: "https://www.jstage.jst.go.jp/article/jila/83/5/83_509/_article/-char/ja", usedFor: "対象を許可済みの街路樹・公園樹に限定する前提" }, { name: "住民参加型の道路維持管理活動を行う団体への行政支援の効果に関する研究", url: "https://www.jstage.jst.go.jp/article/aijt/32/80/32_446/_article/-char/ja", usedFor: "道具・保険・回収を担う中間支援の必要性を検討する材料" }],
