      sources: [{ name: "国土交通省 ベビーカーマークについてのお知らせ", url: "https://www.mlit.go.jp/sogoseisaku/barrierfree/sosei_barrierfree_tk_000091.html", usedFor: "周囲への理解・配慮を求める現状の周知を確認" }, { name: "国土交通省 公共交通事業者に向けた接遇ガイドライン", url: "https://www.mlit.go.jp/common/001236569.pdf", usedFor: "固定中の車内アナウンスという好事例を確認。効果の根拠には使用しない。" }, { name: "国土交通省 乗合バスにおける二人乗りベビーカーの利用", url: "https://www.mlit.go.jp/sogoseisaku/barrierfree/sosei_barrierfree_tk_000224.html", usedFor: "安全な固定・待機が現実の運行場面であることを確認" }],
